import sys, os, json
MODE=os.environ.get("MODE","still")
NAME=os.environ.get("BOTNAME","B")
pid=int(sys.stdin.readline().strip())
W,H=map(int,sys.stdin.readline().split())
prod=list(map(int,sys.stdin.readline().split()))
print(NAME, flush=True)
STILL,N,E,S,Wd=0,1,2,3,4
def nb(i):
    x=i%W; y=i//W
    return {N:((y-1)%H)*W+x, E:y*W+((x+1)%W), S:((y+1)%H)*W+x, Wd:y*W+((x-1)%W)}
NB=[nb(i) for i in range(W*H)]
turn=0
# parse mode
kind=MODE.split(":")[0]
arg=int(MODE.split(":")[1]) if ":" in MODE else 10**9
while True:
    line=sys.stdin.readline()
    if not line: break
    toks=list(map(int,line.split()))
    own=[]; i=0
    while len(own)<W*H:
        own += [toks[i]]*toks[i+1-1+1] if False else [toks[i+1]]*toks[i]
        i+=2
    st=toks[i:i+W*H]
    turn+=1
    mv=[]
    if kind=="expand" and turn<=arg:
        for c in range(W*H):
            if own[c]!=pid or st[c]==0: continue
            best=None
            for d,j in NB[c].items():
                if own[j]==0 and st[j]<st[c]:
                    key=(st[j]-prod[j]*3, st[j])
                    if best is None or key<best[0]: best=(key,d)
            if best: mv.append(f"{c%W} {c//W} {best[1]}")
    elif kind=="attack" and turn>=arg:
        for c in range(W*H):
            if own[c]!=pid or st[c]==0: continue
            got=False
            for d,j in NB[c].items():
                if own[j] not in (0,pid): mv.append(f"{c%W} {c//W} {d}"); got=True; break
            if not got:
                for d,j in NB[c].items():
                    if own[j]==0 and st[j]<st[c]: mv.append(f"{c%W} {c//W} {d}"); break
    print(" ".join(mv), flush=True)
