import subprocess, os, json, glob, tempfile, shutil, re
EXE="/workspace/executable"
def game(seed,w,h,bots,quiet=False,extra=None,timeout=600,notimeout=True,dims=True):
    d=tempfile.mkdtemp(dir="/tmp")
    args=[EXE,"-s",str(seed),"-i",d]
    if dims: args+=["-d",f"{w} {h}"]
    if notimeout: args.append("-t")
    if quiet: args.append("-q")
    if extra: args+=extra
    args+=bots
    r=subprocess.run(args,capture_output=True,cwd=d,timeout=timeout,text=True)
    files=glob.glob(os.path.join(d,"*.hlt"))
    rep=json.load(open(files[0])) if files else None
    raw=open(files[0]).read() if files else None
    logs={os.path.basename(f):open(f).read() for f in glob.glob(os.path.join(d,"*.log"))}
    shutil.rmtree(d)
    return r.stdout,r.stderr,rep,logs,raw
def stats(rep):
    n=rep['num_players']; F=rep['frames']
    T=[[0]*len(F) for _ in range(n+1)]; S=[[0]*len(F) for _ in range(n+1)]
    for f,fr in enumerate(F):
        for row in fr:
            for o,s in row:
                T[o][f]+=1; S[o][f]+=s
    la=[0]*(n+1)
    for p in range(1,n+1):
        la[p]=max([f for f in range(len(F)) if T[p][f]>0] or [0])
    return T,S,la
def parse_ranks(out):
    res={}
    for m in re.finditer(r"Player #(\d+), (.*?), came in rank #(\d+) and was last alive on frame #(\d+)!", out):
        res[int(m.group(1))]=(m.group(2),int(m.group(3)),int(m.group(4)))
    return res
