    res={}
    cands={
      'last_T_at_last': lambda p:(-la[p], -T[p][la[p]], -p),
      'last_maxT'      : lambda p:(-la[p], -max(T[p]), -p),
      'last_sumT'      : lambda p:(-la[p], -sum(T[p]), -p),
      'last_T_S'       : lambda p:(-la[p], -T[p][la[p]], -S[p][la[p]], -p),
      'last_T_Sasc'    : lambda p:(-la[p], -T[p][la[p]], S[p][la[p]], -p),
      'last_T_idasc'   : lambda p:(-la[p], -T[p][la[p]], p),
    }
    for name,f in cands.items():
        order=sorted(ps,key=f)
        pred={p:i+1 for i,p in enumerate(order)}
        res[name]= all(pred[p]==rk[p][1] for p in ps)
